/* ═══ BIZ-LANG-3 · month-name tokens — already-rendered dates follow the
   language switch too (the calendar is NOT converted, only the names). ═══ */
var SLP_MONTHS = [
  /* [ethiopic-AM, greg-EN, greg-AM, OM] */
  ['መስከረም','September','ሴፕቴምበር','Fulbaana'],
  ['ጥቅምት','October','ኦክቶበር','Onkololeessaa'],
  ['ኅዳር','November','ኖቬምበር','Sadaasa'],
  ['ታኅሣሥ','December','ዲሴምበር','Muddee'],
  ['ጥር','January','ጃንዩወሪ','Amajjii'],
  ['የካቲት','February','ፌብሩወሪ','Guraandhala'],
  ['መጋቢት','March','ማርች','Bitootessa'],
  ['ሚያዝያ','April','ኤፕሪል','Obora Guddaa'],
  ['ግንቦት','May','ሜይ','Obora Diqqaa'],
  ['ሰኔ','June','ጁን','Waxabajjii'],
  ['ሐምሌ','July','ጁላይ','Adoolessa'],
  ['ነሐሴ','August','ኦገስት','Hagayya'],
  ['ጳጉሜ', null, null, 'Pagumee']
];
function slpSwapMonths(s) {
  var out = s, changed = false;
  for (var i = 0; i < SLP_MONTHS.length; i++) {
    var m = SLP_MONTHS[i];
    try {
      if (CUR === 'om') {
        if (m[0] && out.indexOf(m[0]) > -1) { out = out.split(m[0]).join(m[3]); changed = true; }
        if (m[1]) {
          var r1 = new RegExp('\\b' + m[1] + '\\b', 'g');
          if (r1.test(out)) { out = out.replace(r1, m[3]); changed = true; }
        }
      } else if (CUR === 'am') {
        if (m[1]) {
          var r2 = new RegExp('\\b' + m[1] + '\\b', 'g');
          if (r2.test(out)) { out = out.replace(r2, m[2]); changed = true; }
        }
      }
    } catch (e) {}
  }
  return changed ? out : null;
}

